from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/guard-body';O.mkdir(parents=True,exist_ok=True);html=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page(viewport={'width':1440,'height':1000});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready');p.locator('.kinetic-launch button').click();rows=[]
 for id,mode in [('chun','low'),('iori','high'),('luke','armor'),('mai','high'),('ryu','hurt')]:
  r=p.evaluate('''({id,mode})=>{const A=SVG_FIGHTER,G=A.state;A.start(id,'ryu','training','classic',17);G.paused=true;document.getElementById('dummy').value='idle';document.getElementById('autohp').checked=false;A.teleport(0,540);A.teleport(1,700);A.step();if(mode==='low'){A.press(0,'left');A.press(0,'down');}else if(mode==='high')A.press(0,'left');if(mode==='armor')A.inputMove(0,'DI');A.inputMove(1,mode==='low'?'cMK':'sMP');const f=A.fighters[0];for(let i=0;i<80;i++){A.step();if(G.lastCombatEvent?.defender===0)break;}A.renderFraction(1);const renderer=f.inkRenderer,root=renderer.group,arms=['front-arm','rear-arm'].map(part=>{const arm=root.querySelector('[data-ink-part="'+part+'"]');return [...arm.querySelectorAll('[data-hand]')].filter(e=>e.getAttribute('display')==='inline').map(e=>e.dataset.hand);}),expressions=[...root.querySelectorAll('[data-expression]')].filter(e=>e.getAttribute('display')==='inline').map(e=>e.dataset.expression),count=root.querySelectorAll('*').length;for(let i=0;i<12;i++)A.renderFraction(1);const pose=A.visualPose(f);return {id,mode,event:G.lastCombatEvent?.type,state:f.state,attack:f.attack?.m.id,arms,expressions,stable:count===root.querySelectorAll('*').length,variants:root.querySelectorAll('[data-hand]').length,fanGrip:id!=='mai'||arms[0][0]==='grip'&&renderer.frontArm.fan.parentNode===renderer.frontArm.hands.grip.parentNode,hasFaces:['guard','brace'].every(v=>root.querySelectorAll('[data-expression="'+v+'"]').length===2)};}''',{'id':id,'mode':mode});rows.append(r)
  if id in ['chun','iori','luke']:p.locator('#game').screenshot(path=str(O/(id+'-appearance.png')))
 b.close()
for r in rows:print(r)
passed=not errors and all(r['stable'] and r['hasFaces'] and r['fanGrip'] and all(len(a)==1 for a in r['arms']) and r['variants']==10 for r in rows) and rows[0]['event']=='block' and rows[1]['event']=='block' and rows[2]['event']=='armor' and rows[2]['attack']=='DI' and 'brace' in rows[2]['expressions'] and 'hurt' in rows[4]['expressions']
(O/'appearance.json').write_text(json.dumps({'htmlSha256':hashlib.sha256(html).hexdigest(),'passed':passed,'rows':rows,'errors':errors},indent=2));assert passed
